//! The cross-provider handoff suite, ported from
//! `packages/ai/test/cross-provider-handoff.test.ts` at commit
//! `60e7e76bd7ea25cad1dd6f3f1ce0d18814a42759`: contexts generated by one
//! provider/model must be consumable by another — tool call id formats,
//! thinking blocks, and message shapes riding the round trip.
//!
//! Like upstream's `it.skipIf`, the suite without any provider credential
//! returns early; fixtures are generated fresh on each run against the live
//! providers the local credential store and env carry.

#![expect(
    clippy::too_many_lines,
    reason = "the fixture and handoff drivers mirror upstream's flat structure"
)]
#![expect(
    clippy::print_stdout,
    reason = "the suite logs fixture and handoff progress like upstream's console.log"
)]
#![expect(
    deprecated,
    reason = "the suite drives the deprecated compat surface, upstream's cast getModel"
)]
#![expect(
    clippy::significant_drop_tightening,
    reason = "the registry guard is held for each test's whole run on purpose; the suites must not interleave"
)]

use std::collections::{BTreeMap, BTreeSet};
use std::sync::{Arc, Mutex, OnceLock};

use pi_ai::auth::resolve::now_ms;
use pi_ai::compat::{complete_simple, get_env_api_key, get_model};
use pi_ai::types::{
    Api, AssistantBlock, Context, Message, Model, ProviderHeaders, SimpleStreamOptions, StopReason,
    ThinkingLevel, ToolResultBlock, ToolResultMessage, UserContent, UserMessage,
};

mod common;

/// The tool the fixtures exercise, upstream's `testTool` over
/// `Type.Object({ value: Type.Number() })` — typebox requires every property.
fn test_tool() -> pi_ai::types::Tool {
    pi_ai::types::Tool {
        name: "double_number".to_owned(),
        description: "Doubles a number and returns the result".to_owned(),
        parameters: serde_json::json!({
            "type": "object",
            "properties": {
                "value": { "type": "number", "description": "A number to double" }
            },
            "required": ["value"]
        }),
        constrained_sampling: None,
    }
}

/// One provider/model pair the suite generates a fixture for and handoffs
/// into, upstream's `ProviderModelPair`.
#[derive(Clone, Copy)]
struct ProviderModelPair {
    provider: &'static str,
    model: &'static str,
    label: &'static str,
    api_override: Option<&'static str>,
    upstream_api_key_env: Option<&'static str>,
}

const fn pair(
    provider: &'static str,
    model: &'static str,
    label: &'static str,
) -> ProviderModelPair {
    ProviderModelPair {
        provider,
        model,
        label,
        api_override: None,
        upstream_api_key_env: None,
    }
}

